+
+static const value_string trel_command_vals[] = {
+    { TREL_TYPE_BROADCAST,                  "TREL Advertisment" },
+    { TREL_TYPE_UNICAST,                   "TREL Unicast Response" },
+    { TREL_TYPE_ACK,                      "TREL Acknowledgement"},
+    { 0, NULL}
+};
